use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let strings = match input {
        Value::Array(arr) => arr.into_iter().filter_map(|v| v.as_str()).collect::<Vec<&str>>(),
        _ => return Value::String("".to_string()),
    };

    if strings.is_empty() {
        return Value::String("".to_string());
    }

    let mut prefix = strings[0].to_string();
    for string in strings.iter().skip(1) {
        while !string.starts_with(&prefix) {
            prefix.pop();
            if prefix.is_empty() {
                return Value::String("".to_string());
            }
        }
    }
    Value::String(prefix)
}
